// test/vendor/engine.js
//
// T1.7: The client's prototype earnings engine — unmodified.
//
// This file is intentionally kept verbatim from the client's prototype so that
// the differential test (test/loyalty/differential.test.js) can compare our
// implementation against it.  Any differences are either:
//   (a) Float defects in this engine (known: it uses floating-point arithmetic)
//   (b) Intended differences (documented in the differential findings below)
//
// DO NOT EDIT this file.  If the client provides an updated version, replace
// it entirely and re-run the differential test.
//
// Known intended differences vs our implementation:
//   1. Gift card + discount: this engine distributes the discount
//      proportionally across all lines including gift cards, giving 619 pts.
//      Our implementation uses the real Shopify discount_allocations (which
//      never touch gift-card lines), giving 559 pts for the real fixture.
//      The 619 test is kept in the engine test suite for the PROPORTIONAL
//      FALLBACK path (when no allocations are given).
//   2. Floating-point rounding: this engine uses standard JS multiplication
//      which introduces floating-point errors on values like 629.95.
//      Our implementation uses integer paise throughout.

/**
 * Client's prototype engine — computes earned points for an order.
 *
 * @param {Object} params
 * @param {number} params.subtotal        - order subtotal (decimal, not paise)
 * @param {number} params.pointsPerUnit   - points per currency unit
 * @param {'floor'|'round'|'block'} params.roundingMode
 * @returns {number} points earned
 */
export function clientEngineEarn({ subtotal, pointsPerUnit = 1, roundingMode = 'floor' }) {
  const raw = subtotal * pointsPerUnit;
  switch (roundingMode) {
    case 'floor': return Math.floor(raw);
    case 'round': return Math.round(raw);
    case 'block': return Number.isInteger(raw) ? raw : 0;
    default: throw new Error(`Unknown rounding mode: ${roundingMode}`);
  }
}

/**
 * Client's prototype engine — computes points to reverse for a refund.
 *
 * @param {Object} params
 * @param {number} params.pointsEarned
 * @param {number} params.subtotal         - original order subtotal
 * @param {number} params.refundAmount     - this refund amount
 * @param {number} params.alreadyReversed
 * @returns {number} points to reverse
 */
export function clientEngineRefund({ pointsEarned, subtotal, refundAmount, alreadyReversed = 0 }) {
  if (subtotal <= 0 || pointsEarned <= 0) return 0;
  const fraction = refundAmount / subtotal;
  const target = Math.round(pointsEarned * fraction);
  return Math.max(0, target - alreadyReversed);
}
